<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{api}from'../api';import{ElMessage,ElMessageBox}from'element-plus';
const rows=ref<any[]>([]),total=ref(0),page=ref(1),keyword=ref(''),dialog=ref(false),editing=ref<number|null>(null),fileRef=ref<HTMLInputElement|null>(null);
const form=reactive<any>({type:'SINGLE',content:'',optionsText:'A. 选项一\nB. 选项二',correctAnswer:'A',analysis:'',difficulty:'MEDIUM',knowledgePoint:'',defaultScore:5});
async function load(){const r:any=await api.questions({page:page.value,size:10,keyword:keyword.value});rows.value=r.records;total.value=r.total}
function open(row?:any){editing.value=row?.id??null;Object.assign(form,row?{...row,optionsText:(row.options||[]).join('\n')}:{type:'SINGLE',content:'',optionsText:'A. 选项一\nB. 选项二',correctAnswer:'A',analysis:'',difficulty:'MEDIUM',knowledgePoint:'',defaultScore:5});dialog.value=true}
async function save(){const data={...form,options:form.optionsText.split('\n').map((x:string)=>x.trim()).filter(Boolean)};delete data.optionsText;if(editing.value)await api.updateQuestion(editing.value,data);else await api.createQuestion(data);ElMessage.success('保存成功');dialog.value=false;load()}
async function remove(id:number){await ElMessageBox.confirm('确定删除该题目？');await api.deleteQuestion(id);load()}
async function exportFile(){const token=localStorage.getItem('examforge_token');const r=await fetch('/api/questions/export',{headers:{Authorization:`Bearer ${token}`}});const b=await r.blob();const u=URL.createObjectURL(b);const a=document.createElement('a');a.href=u;a.download='examforge-questions.xlsx';a.click();URL.revokeObjectURL(u)}
async function importFile(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;const fd=new FormData();fd.append('file',f);const token=localStorage.getItem('examforge_token');const r=await fetch('/api/questions/import',{method:'POST',headers:{Authorization:`Bearer ${token}`},body:fd});const b=await r.json();ElMessage.success(`导入完成：成功 ${b.data?.imported||0}，跳过 ${b.data?.skipped||0}`);load()}
onMounted(load);
</script>
<template><div class="page"><div class="page-header"><div><h2 class="page-title">题库管理</h2><p class="muted">维护考试题目，支持 Excel 批量导入导出</p></div><el-button type="primary" @click="open()">新增题目</el-button></div><div class="toolbar"><el-input v-model="keyword" placeholder="搜索题干" style="max-width:260px" clearable @keyup.enter="page=1;load()"/><el-button @click="page=1;load()">搜索</el-button><el-button @click="exportFile">导出 Excel</el-button><el-button @click="fileRef?.click()">导入 Excel</el-button><input ref="fileRef" type="file" accept=".xlsx" hidden @change="importFile"/></div><div class="content-card"><el-table :data="rows" stripe><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="type" label="题型" width="110"><template #default="s"><el-tag>{{s.row.type}}</el-tag></template></el-table-column><el-table-column prop="content" label="题干" min-width="300" show-overflow-tooltip/><el-table-column prop="knowledgePoint" label="知识点" width="140"/><el-table-column prop="defaultScore" label="分值" width="80"/><el-table-column label="操作" width="140"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row.id)">删除</el-button></template></el-table-column></el-table><el-pagination style="margin-top:16px;justify-content:flex-end" v-model:current-page="page" :total="total" :page-size="10" @current-change="load"/></div><el-dialog v-model="dialog" :title="editing?'编辑题目':'新增题目'" width="620px"><el-form label-position="top"><el-form-item label="题型"><el-select v-model="form.type"><el-option v-for="t in ['SINGLE','MULTIPLE','JUDGE','FILL','SUBJECTIVE']" :key="t" :label="t" :value="t"/></el-select></el-form-item><el-form-item label="题干"><el-input v-model="form.content" type="textarea" :rows="3"/></el-form-item><el-form-item label="选项（每行一个；主观题可留空）"><el-input v-model="form.optionsText" type="textarea" :rows="3"/></el-form-item><el-form-item label="标准答案（多选题用逗号分隔；主观题留空）"><el-input v-model="form.correctAnswer"/></el-form-item><el-form-item label="解析"><el-input v-model="form.analysis"/></el-form-item><el-row :gutter="12"><el-col :span="8"><el-form-item label="难度"><el-select v-model="form.difficulty"><el-option label="简单" value="EASY"/><el-option label="中等" value="MEDIUM"/><el-option label="困难" value="HARD"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="知识点"><el-input v-model="form.knowledgePoint"/></el-form-item></el-col><el-col :span="8"><el-form-item label="分值"><el-input-number v-model="form.defaultScore" :min="0.1" :max="100"/></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
